<template><main class="analysis-screen"><header><div class="brand">⚡ <div><h1>新能源消纳与并网智能调控平台</h1><small>NEW ENERGY · CONSUMPTION ANALYSIS</small></div></div><nav><RouterLink to="/dashboard">功率监测</RouterLink><RouterLink to="/weather">气象观测</RouterLink><RouterLink class="active" to="/analysis">消纳分析</RouterLink></nav></header><section class="content"><div class="title"><div><span>CONSUMPTION CENTER</span><h2>新能源消纳分析</h2><p>实际功率 · 理论功率 · 可利用功率 · 弃电与预测误差</p></div><select v-model="selected"><option v-for="s in stations" :key="s.station_id" :value="s.station_id">{{s.station_id}}</option></select></div><div class="kpis"><div><small>全场消纳率</small><b>{{rate}}</b><i>{{consumption?.comparable_station_count||0}} / {{consumption?.station_count||11}} 个场站同口径</i></div><div><small>全场弃电率</small><b>{{curtailment}}</b><i>可利用功率差额</i></div><div><small>{{selected}} · 预测 MAE</small><b>{{metric(metrics?.mae)}}</b><i>近24小时</i></div><div><small>{{selected}} · 预测 RMSE</small><b>{{metric(metrics?.rmse)}}</b><i>近24小时</i></div></div><div class="grid"><section class="panel"><div class="panel-head"><strong>{{selected}} · 24小时功率消纳</strong><span>实际 / 理论 / 可利用</span></div><div ref="chartEl" class="chart"></div></section><aside class="panel"><div class="panel-head"><strong>消纳质量</strong><span>{{consumption?.quality==='complete'?'完整':consumption?.quality==='partial'?'部分覆盖':'待校验'}}</span></div><div class="quality"><div><small>实际功率</small><b>{{latest?.active_power_mw?.toFixed(2)||'—'}} MW</b></div><div><small>理论功率</small><b>{{latest?.theory_power_mw?.toFixed(2)||'—'}} MW</b></div><div><small>可利用功率</small><b>{{latest?.available_power_mw?.toFixed(2)||'—'}} MW</b></div><div><small>功率缺口</small><b>{{gap}}</b></div></div><p>{{consumption?.warning||'指标由实时功率、理论功率和可利用功率统一计算。'}}</p></aside></div><section class="panel stations-panel"><div class="panel-head"><strong>场站消纳明细</strong><span>缺失字段不参与总比率</span></div><div class="station-table"><div class="station-row station-head"><span>场站</span><span>实际 MW</span><span>理论 MW</span><span>可利用 MW</span><span>消纳率</span><span>弃电率</span></div><div v-for="item in consumption?.station_breakdown||[]" :key="item.station_id" class="station-row"><b>{{item.station_id}}</b><span>{{item.active_power_mw==null?'—':item.active_power_mw.toFixed(2)}}</span><span>{{item.theory_power_mw==null?'缺失':item.theory_power_mw.toFixed(2)}}</span><span>{{item.available_power_mw==null?'缺失':item.available_power_mw.toFixed(2)}}</span><span>{{item.consumption_rate==null?'—':item.consumption_rate.toFixed(2)+'%'}}</span><span>{{item.curtailment_rate==null?'—':item.curtailment_rate.toFixed(2)+'%'}}</span></div></div></section><section class="panel error"><div class="panel-head"><strong>预测误差曲线</strong><span>预测值 − 真实值</span></div><div ref="errorEl" class="error-chart"></div></section></section></main></template>
<script setup lang="ts">import{computed,onMounted,onUnmounted,ref,watch}from'vue';import*as echarts from'echarts';import{platformApi}from'../../api/platform';import type{ConsumptionOverview,ForecastMetrics,PowerPoint,Station}from'../../api/types';const stations=ref<Station[]>([]),selected=ref('FD0001'),consumption=ref<ConsumptionOverview|null>(null),metrics=ref<ForecastMetrics|null>(null),points=ref<PowerPoint[]>([]),chartEl=ref<HTMLElement|null>(null),errorEl=ref<HTMLElement|null>(null);let chart:echarts.ECharts|null=null,errorChart:echarts.ECharts|null=null;const latest=computed(()=>points.value[points.value.length-1]),rate=computed(()=>consumption.value?.consumption_rate==null?'—':`${consumption.value.consumption_rate.toFixed(2)}%`),curtailment=computed(()=>consumption.value?.curtailment_rate==null?'—':`${consumption.value.curtailment_rate.toFixed(2)}%`),gap=computed(()=>latest.value?.available_power_mw==null||latest.value?.active_power_mw==null?'—':`${Math.max(0,latest.value.available_power_mw-latest.value.active_power_mw).toFixed(2)} MW`),metric=(v:number|null|undefined)=>v==null?'—':v.toFixed(3);async function load(){const[s,c,m,p]=await Promise.allSettled([platformApi.stations(),platformApi.consumption(),platformApi.forecastMetrics(selected.value,24),platformApi.powerSeries(selected.value,24)]);if(s.status==='fulfilled')stations.value=s.value;if(c.status==='fulfilled')consumption.value=c.value;if(m.status==='fulfilled')metrics.value=m.value;if(p.status==='fulfilled')points.value=p.value;render()}function tm(v:string){return new Date(v).toLocaleTimeString('zh-CN',{timeZone:'Asia/Shanghai',hour:'2-digit',minute:'2-digit'})}function render(){const x=points.value.map(p=>tm(p.observed_at));if(chartEl.value){chart??=echarts.init(chartEl.value);chart.setOption({tooltip:{trigger:'axis'},legend:{top:0,textStyle:{color:'#9ab7c9'}},grid:{left:45,right:18,top:30,bottom:28},xAxis:{type:'category',data:x,axisLabel:{color:'#7896a8'}},yAxis:{type:'value',axisLabel:{color:'#7896a8'}},dataZoom:[{type:'inside'},{type:'slider',height:12}],series:[{name:'实际功率',type:'line',smooth:true,data:points.value.map(p=>p.active_power_mw),lineStyle:{color:'#39d9ff'}},{name:'理论功率',type:'line',smooth:true,data:points.value.map(p=>p.theory_power_mw),lineStyle:{color:'#ffb45b'}},{name:'可利用功率',type:'line',smooth:true,data:points.value.map(p=>p.available_power_mw),lineStyle:{color:'#3ee5b1'}}]})}if(errorEl.value){errorChart??=echarts.init(errorEl.value);errorChart.setOption({tooltip:{trigger:'axis'},grid:{left:45,right:18,top:18,bottom:28},xAxis:{type:'category',data:x,axisLabel:{color:'#7896a8'}},yAxis:{type:'value',axisLabel:{color:'#7896a8'}},series:[{name:'预测误差',type:'bar',data:points.value.map(p=>p.theory_power_mw==null||p.active_power_mw==null?null:p.theory_power_mw-p.active_power_mw),itemStyle:{color:'#ff8b6b'}}]})}}watch(selected,load);onMounted(load);onUnmounted(()=>{chart?.dispose();errorChart?.dispose()});</script>
