x;line-height:1.6}.stations-panel{margin-top:14px}.station-table{margin-top:12px}.station-row{display:grid;grid-template-columns:1.1fr repeat(5,1fr);gap:8px;align-items:center;padding:9px 4px;border-bottom:1px solid rgba(100,180,210,.1);color:#bfe8f2;font-size:10px}.station-row b{color:#dffaff;font:12px ui-monospace,monospace}.station-head{color:#7896a8;font-size:9px}.error{margin-top:14px}.error-chart{height:220px;margin-top:10px}@media(max-width:900px){.brand{min-width:0}.brand h1{font-size:14px}.content{padding:16px}.grid{grid-template-columns:1fr}.kpis{grid-template-columns:repeat(2,1fr)}}</style>

